import re

def parse_amount(text: str) -> int:
    """
    Parse a money amount typed by a person or exported from a spreadsheet into
    integer cents.
    """
    text = text.strip()
    if not text: raise ValueError("Empty")

    match = re.match(r'^([+-]?)\$?(.*)$', text)
    if not match: raise ValueError("Format")
    sign_str, rest = match.groups()
    if not rest: raise ValueError("No digits")

    if '.' in rest:
        parts = rest.split('.')
        if len(parts) != 2: raise ValueError("Decimal")
        int_str, frac_str = parts
    else:
        int_str, frac_str = rest, ""

    if len(frac_str) > 2: raise ValueError("Fraction")

    if ',' in int_str:
        c_parts = int_str.split(',')
        if not (1 <= len(c_parts[0]) <= 3) or any(len(p) != 3 for p in c_parts[1:]):
            raise ValueError("Comma")

    clean_int = int_str.replace(',', '')
    if not clean_int.isdigit(): raise ValueError("Digits")

    val = int(clean_int) * 100
    if frac_str:
        val += int(frac_str) * (10 if len(frac_str) == 1 else 1)

    return -val if sign_str == '-' else val
"}}, "messages": []}

