from typing import List, Sequence


def allocate_cents(total: int, weights: Sequence[int]) -> List[int]:
    if not weights:
        raise ValueError("weights cannot be empty")
    total_weight = sum(weights)
    if total_weight <= 0:
        raise ValueError("sum of weights must be positive")
    for w in weights:
        if w < 0:
            raise ValueError("weights must be non-negative")

    n = len(weights)
    results = [0] * n
    remainders = []

    for i, w in enumerate(weights):
        share_scaled = total * w
        initial_share = int(share_scaled / total_weight)
        results[i] = initial_share
        rem_num = share_scaled - (initial_share * total_weight)
        remainders.append((rem_num, i))

    diff = total - sum(results)

    # Sort by remainder DESC, then index ASC. 
    # Using (rem, -index) with reverse=True achieves this.
    remainders.sort(key=lambda x: (x[0], -x[1]), reverse=True)

    if diff > 0:
        for i in range(int(diff)):
            idx = remainders[i][1]
            results[idx] += 1
    elif diff < 0:
        for i in range(int(abs(diff))):
            idx = remainders[i][1]
            results[idx] -= 1

    return results
